    { subject: "Language", type: "Pedagogy", tagText: "Authentic Materials", question: "Which of the following is considered an 'Authentic material' for language teaching?", options: ["A real newspaper advertisement, restaurant menu, or bus timetable", "A drill sheet of random isolated grammar rules", "A word-list dictionary excerpt with no sentences", "A phonetics test question"], answer: 0, explanation: "Authentic materials are real-world texts produced for genuine communicative purposes rather than pedagogical drills." },
    { subject: "Language", type: "Grammar", tagText: "Tenses", question: "Fill in the blank with the correct tense: 'The sun ____ in the east.'", options: ["rises", "is rising", "rose", "has risen"], answer: 0, explanation: "Universal eternal scientific truths are always expressed in the Simple Present Tense ('rises')." },
    { subject: "Language", type: "Vocabulary", tagText: "Antonym", question: "Choose the antonym of 'Transparent' (पारदर्शक):", options: ["Opaque (अपारदर्शक)", "Clear", "Bright", "Lucid"], answer: 0, explanation: "'Transparent' allows light to pass clearly; its opposite is 'Opaque' (not allowing light through)." },
    { subject: "Language", type: "Grammar", tagText: "Direct Indirect", question: "Change to reported speech: She said, 'I can solve this puzzle.'", options: ["She said that she could solve that puzzle.", "She said that she can solve this puzzle.", "She says that she could solve that puzzle.", "She said I could solve this puzzle."], answer: 0, explanation: "'can' shifts to 'could', and demonstrative 'this' shifts to 'that' in indirect past reporting." },
    { subject: "Language", type: "Pedagogy", tagText: "Peer Tutoring", question: "When a fluent reader pairs up with a struggling reader to read a storybook together, this instructional technique is known as:", options: ["Paired reading / Peer tutoring (जोडीदार वाचन)", "Silent independent study", "Summative testing", "Isolated rote drill"], answer: 0, explanation: "Paired reading leverages collaborative peer modeling to boost reading confidence and decoding fluency." }
